  functions: { title:"Principales funciones simbólicas de Quirón", cards:[{number:"01",title:"Identificar",text:"Poner de relieve una zona de sensibilidad o aprendizaje personal."},{number:"02",title:"Comprender",text:"Explorar las reacciones, experiencias y significados relacionados con esa zona."},{number:"03",title:"Integrar",text:"Desarrollar una relación más consciente con lo que antes parecía difícil de aceptar."},{number:"04",title:"Transmitir",text:"Transformar la experiencia en comprensión, compasión o capacidad para apoyar a los demás."}] },
