  retrograde: { kicker:"Una expresión más interior", title:"¿Qué significa Quirón retrógrado?", paragraphs:["Visto desde la Tierra, Quirón puede presentar un movimiento retrógrado aparente, como otros cuerpos del sistema solar.", "En astrología, Quirón retrógrado suele interpretarse como una expresión más interior de sus temas simbólicos.", "Esta interpretación puede poner el acento en la introspección y en la integración personal de ciertas experiencias."], cardSymbol:"⚷℞", cardTitle:"Una invitación a la introspección", items:["Observar tus reacciones", "Identificar sensibilidades recurrentes", "Reconsiderar interpretaciones del pasado", "Desarrollar la autoaceptación", "Integrar la experiencia con discernimiento"] },
