  jsonLd: { headline:"Chiron in der Astrologie", description:"Umfassender Leitfaden zur astrologischen Symbolik Chirons in Zeichen, Häusern und Aspekten des Geburtshoroskops." },
  hero: { badge:"⚷ Asteroiden und Geburtshoroskop", title:"Chiron in der Astrologie", lead:"In der Astrologie wird Chiron als Symbol für Verletzlichkeit, Lernen und innere Transformation gedeutet.", createChart:"Mein kostenloses Geburtshoroskop erstellen", seeSigns:"Die 12 Zeichen ansehen" },
  introduction: { kicker:"Einen sensiblen Bereich verstehen", title:"Wofür steht Chiron im Geburtshoroskop?", paragraphs:["In der Astrologie wird Chiron meist mit einem Bereich der Verletzlichkeit, einer Erfahrung, die Verständnis verlangt, und der Fähigkeit verbunden, aus Schwierigkeiten Weisheit zu entwickeln.", "Seine Stellung im Geburtshoroskop wird über Zeichen, Haus und Aspekte gedeutet. Das Zeichen beschreibt, wie sich diese Sensibilität symbolisch ausdrückt, während das Haus auf den betroffenen Lebensbereich hinweist.", "Chiron sollte nicht als Diagnose oder Beweis einer tatsächlichen Verletzung verstanden werden. In der Astrologie dient er als Symbol zur persönlichen Selbsterkundung."] },
  structure: { title:"Chiron, Verletzlichkeit und Transformation", cards:[{symbol:"⚷",title:"Der sensible Bereich",text:"Chiron kann einen Bereich symbolisieren, in dem man sich besonders verletzlich fühlt oder noch lernt."},{symbol:"✦",title:"Verständnis",text:"Seine Deutung kann helfen, bestimmten Erfahrungen eine symbolische Bedeutung zu geben."},{symbol:"🌱",title:"Transformation",text:"Chiron wird auch damit verbunden, Schwierigkeiten in Verständnis, Reife oder Unterstützung für andere zu verwandeln."}] },
  functions: { title:"Die wichtigsten symbolischen Funktionen Chirons", cards:[{number:"01",title:"Erkennen",text:"Einen Bereich der Sensibilität oder des persönlichen Lernens sichtbar machen."},{number:"02",title:"Verstehen",text:"Reaktionen, Erfahrungen und Bedeutungen erkunden, die mit diesem Bereich verbunden sind."},{number:"03",title:"Integrieren",text:"Eine bewusstere Beziehung zu dem entwickeln, was früher schwer anzunehmen war."},{number:"04",title:"Weitergeben",text:"Erfahrung in Verständnis, Mitgefühl oder die Fähigkeit verwandeln, andere zu unterstützen."}] },
